using System.IO.Abstractions.TestingHelpers;
using System.Text;
using Mutagen.Bethesda.Plugins;
using Mutagen.Bethesda.Plugins.Binary.Parameters;
using Mutagen.Bethesda.Plugins.Order;
using Mutagen.Bethesda.Plugins.Records;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// Armors of two official DarkStar patches whose world models are split by other subrecords. Upstream's split-pair
// change (#700) made the overlay throw on them (issue #743): with both halves already read, a later FLLD read nothing
// and the gendered factory threw "Expected things to be read". Each record is read from a plugin made of its patch's
// real header and the record, with both readers: the models come out the same from both, and the record is
// written back byte for byte, in the file's own subrecord order (FE00085D keeps its light layers after STOP AFSG,
// though the gendered model writes each next to its model).
// - darkstarpatch_bountyhunteroutfitz.esm FE00085D: MOD2 MOD4 ... STOP AFSG FLLD FLLD (both models first, their
//   light layers at the end)
// - darkstarpatch_terranarmada.esm FE0008FC: MOD2 FLLD FLLD (a male model, then a female half holding only FLLD)
// - darkstarpatch_terranarmada.esm FE0008FD: MOD2 FLLD MOD4 FLLD (the usual order)
// - darkstarpatch_terranarmada.esm FE000812: MOD2 MO2F FLLD XFLG FLLD (the model's own parts out of order, the field
//   read three times in a row)
public class DarkStarPatchArmorModelTests
{
    private const string BountyTes4 = "";
    private const string BountyArmo = "";
    private const string TerranTes4 = "";
    private const string TerranArmoFc = "";
    private const string TerranArmo812 = "";
    private const string TerranArmoFd = "";

    private static byte[] Hex(string hex) => Convert.FromHexString(hex);

    private static readonly LoadOrder<IModMasterStyledGetter> Lo = new(new IModMasterStyledGetter[]
    {
        new KeyedMasterStyle(ModKey.FromFileName("Starfield.esm"), MasterStyle.Full),
        new KeyedMasterStyle(ModKey.FromFileName("sfbgs00d.esm"), MasterStyle.Full),
        new KeyedMasterStyle(ModKey.FromFileName("SFBGS050.esm"), MasterStyle.Full),
        new KeyedMasterStyle(ModKey.FromFileName("bountyhunter_outfit_z.esm"), MasterStyle.Small),
        new KeyedMasterStyle(ModKey.FromFileName("darkstar.esm"), MasterStyle.Full),
        new KeyedMasterStyle(ModKey.FromFileName("SFBGS006.esm"), MasterStyle.Medium),
        new KeyedMasterStyle(ModKey.FromFileName("sfbgs003.esm"), MasterStyle.Medium),
        new KeyedMasterStyle(ModKey.FromFileName("darkstarpatch_bountyhunteroutfitz.esm"), MasterStyle.Small),
        new KeyedMasterStyle(ModKey.FromFileName("darkstarpatch_terranarmada.esm"), MasterStyle.Small),
    });

    private static byte[] Group(string label, byte[] records)
    {
        var s = new MemoryStream();
        s.Write(Encoding.ASCII.GetBytes("GRUP"));
        s.Write(BitConverter.GetBytes(24 + records.Length));
        s.Write(Encoding.ASCII.GetBytes(label));
        s.Write(BitConverter.GetBytes(0));
        s.Write(new byte[8]);
        s.Write(records);
        return s.ToArray();
    }

    private static byte[] RecordBytes(byte[] file, uint formId)
    {
        int p = 24 + BitConverter.ToInt32(file, 4);
        while (p + 24 <= file.Length)
        {
            var sig = Encoding.ASCII.GetString(file, p, 4);
            int size = BitConverter.ToInt32(file, p + 4);
            if (sig == "GRUP") { p += 24; continue; }
            if (BitConverter.ToUInt32(file, p + 12) == formId) return file.AsSpan(p, 24 + size).ToArray();
            p += 24 + size;
        }
        throw new InvalidOperationException($"{formId:X8} not written");
    }

    public static IEnumerable<object[]> Records() => new[]
    {
        new object[] { "darkstarpatch_bountyhunteroutfitz.esm", BountyTes4, BountyArmo, 0xFE00085Du },
        new object[] { "darkstarpatch_terranarmada.esm", TerranTes4, TerranArmoFc, 0xFE0008FCu },
        new object[] { "darkstarpatch_terranarmada.esm", TerranTes4, TerranArmoFd, 0xFE0008FDu },
        new object[] { "darkstarpatch_terranarmada.esm", TerranTes4, TerranArmo812, 0xFE000812u },
    };

    [Theory]
    [MemberData(nameof(Records))]
    public void SplitWorldModels_ReadByBothReaders_WriteBackByteForByte(string fileName, string tes4, string armo, uint formId)
    {
        var fs = new MockFileSystem();
        var path = Path.Combine("C:", "Data", fileName);
        fs.Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        fs.File.WriteAllBytes(path, Hex(tes4).Concat(Group("ARMO", Hex(armo))).ToArray());
        var param = new BinaryReadParameters { FileSystem = fs, MasterFlagsLookup = Lo };
        var mods = new IStarfieldModGetter[]
        {
            StarfieldMod.CreateFromBinary(path, StarfieldRelease.Starfield, param),
            StarfieldMod.CreateFromBinaryOverlay(path, StarfieldRelease.Starfield, param),
        };
        foreach (var mod in mods)
        {
            var armor = mod.Armors.ShouldHaveSingleItem();
            var model = armor.WorldModel.ShouldNotBeNull();
            model.Male.ShouldNotBeNull().File.ShouldNotBeNull();
            var outPath = Path.Combine("C:", "Out", fileName);
            fs.Directory.CreateDirectory(Path.GetDirectoryName(outPath)!);
            mod.WriteToBinary(outPath, new BinaryWriteParameters
            {
                FileSystem = fs,
                MasterFlagsLookup = Lo,
                MastersListContent = MastersListContentOption.NoCheck,
                MastersListOrdering = new MastersListOrderingByLoadOrder(mod.MasterReferences.Select(m => m.Master)),
            });
            RecordBytes(fs.File.ReadAllBytes(outPath), formId).ShouldBe(Hex(armo));
        }
        mods[0].Armors.Single().Equals(mods[1].Armors.Single()).ShouldBeTrue();
    }

    // A changed record is written in Mutagen's order: each light layer next to its model
    [Fact]
    public void ChangedSplitWorldModel_WritesInNormalOrder()
    {
        var fs = new MockFileSystem();
        var path = Path.Combine("C:", "Data", "darkstarpatch_bountyhunteroutfitz.esm");
        fs.Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        fs.File.WriteAllBytes(path, Hex(BountyTes4).Concat(Group("ARMO", Hex(BountyArmo))).ToArray());
        var mod = StarfieldMod.CreateFromBinary(path, StarfieldRelease.Starfield,
            new BinaryReadParameters { FileSystem = fs, MasterFlagsLookup = Lo });
        mod.Armors.Single().WorldModel!.Female!.LightLayer = (Light.LightLayer)2;
        var outPath = Path.Combine("C:", "Out", "darkstarpatch_bountyhunteroutfitz.esm");
        fs.Directory.CreateDirectory(Path.GetDirectoryName(outPath)!);
        mod.WriteToBinary(outPath, new BinaryWriteParameters
        {
            FileSystem = fs,
            MasterFlagsLookup = Lo,
            MastersListContent = MastersListContentOption.NoCheck,
            MastersListOrdering = new MastersListOrderingByLoadOrder(mod.ModHeader.MasterReferences.Select(m => m.Master)),
        });
        var written = RecordBytes(fs.File.ReadAllBytes(outPath), 0xFE00085D);
        var types = new List<string>();
        for (int p = 24; p + 6 <= written.Length; p += 6 + BitConverter.ToUInt16(written, p + 4))
        {
            var type = Encoding.ASCII.GetString(written, p, 4);
            if (type is "MOD2" or "MOD4" or "FLLD") types.Add(type);
        }
        types.ShouldBe(new[] { "MOD2", "FLLD", "MOD4", "FLLD" });
    }
}
